{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter."""


def _quote(value):
    if any(ch in value for ch in (',', '"', '\r', '\n')):
        return '"' + value.replace('"', '""') + '"'
    return value


def export_csv(rows, columns):
    col_list = list(columns)
    seen = set()
    for col in col_list:
        if not isinstance(col, str):
            raise ValueError("Column names must be strings")
        if col in seen:
            raise ValueError("Duplicate column names")
        seen.add(col)

    lines = []
    lines.append(','.join(_quote(col) for col in col_list))
    for row in rows:
        lines.append(','.join(_quote(str(row.get(col, '')) if row.get(col, '') is not None else '') for col in col_list))
    return '\r\n'.join(lines) + '\r\n'
